codes.java:
class Order {
    boolean paid;

    Order(boolean paid) {
        this.paid = paid;
    }
}

public class Main {
    public static void process(Order order) {
        if (order == null) {
            return;          // nothing to do, leave early
        }
        if (!order.paid) {
            return;          // skip unpaid orders
        }
        ship(order);         // the main work, nice and flat
    }

    public static void ship(Order order) {
        System.out.println("Shipping order...");
    }

    public static void main(String[] args) {
        process(new Order(true));
        process(new Order(false));
        process(null);
    }
}

codes.cpp:
#include <iostream>
using namespace std;

class Order {
public:
    bool paid;
    Order(bool paid) : paid(paid) {}
};

void ship(Order& order) {
    cout << "Shipping order..." << endl;
}

void process(Order* order) {
    if (order == nullptr) {
        return;          // nothing to do, leave early
    }
    if (!order->paid) {
        return;          // skip unpaid orders
    }
    ship(*order);         // the main work, nice and flat
}

int main() {
    Order paidOrder(true);
    Order unpaidOrder(false);
    process(&paidOrder);
    process(&unpaidOrder);
    process(nullptr);
    return 0;
}

